	t.Helper()
	for _, info := range m.GetHeaderInfo("") {
		if info.Key == key {
			return info.Value
		}
	}
	return ""
}

func lvl1Names(m Model) []string {
	var out []string
	for _, r := range m.registryBrowser.searchTable.Visible() {
		out = append(out, r.img.Name)
	}
	return out

